CREATE OR REPLACE FUNCTION public.icash_settle_unstarted_recorded_call(p_id uuid, p_account uuid, p_operation text, p_receipt jsonb, p_components jsonb, p_evidence text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.icash_call_recordings;o public.icash_operation_spend;prior icash_recording_private.terminal_cost_receipts;
 cat text;part jsonb;n numeric;total numeric:=0;charge bigint;gather bigint;basis text:='verified';
begin
 -- Same budget -> operation lock order as the existing ledger.
 perform 1 from public.icash_operating_budget where id=1 for update;
 select * into o from public.icash_operation_spend where operation_key=p_operation and account_id=p_account for update;
 if not found or o.state not in ('dispatched','settled') or o.customer_price_micros is not null then return null;end if;
 select * into r from public.icash_call_recordings where id=p_id and account_id=p_account and operation_key=p_operation for update;
 if not found or r.state not in ('declined','failed','absent') or r.call_sid is null or r.start_claimed_at is not null or r.recording_sid is not null or r.conversation_id is not null
  or exists(select 1 from public.icash_live_conversations c where c.operation_key=p_operation)
  or exists(select 1 from public.icash_voice_jobs j where j.id=r.voice_job_id and j.conversation_id is not null) then return null;end if;
 if not icash_recording_private.keys(p_receipt,array['providerAccountSid','callSid','fromPhone','toPhone','status','durationSeconds','priceMicros','currency','speechGatherUsed'])
  or row(p_receipt->>'providerAccountSid',p_receipt->>'callSid',p_receipt->>'fromPhone',p_receipt->>'toPhone') is distinct from row(r.provider_account_sid,r.call_sid,r.from_phone,r.to_phone)
  or coalesce(p_receipt->>'status','') not in ('completed','busy','failed','no-answer','canceled') or p_receipt->>'currency' is distinct from 'USD'
  or jsonb_typeof(p_receipt->'speechGatherUsed') is distinct from 'boolean'
  or jsonb_typeof(p_receipt->'durationSeconds') is distinct from 'number' or (p_receipt->>'durationSeconds')::numeric<>trunc((p_receipt->>'durationSeconds')::numeric)
  or (p_receipt->>'durationSeconds')::numeric not between 0 and 600
  or jsonb_typeof(p_receipt->'priceMicros') is distinct from 'number' or (p_receipt->>'priceMicros')::numeric<>trunc((p_receipt->>'priceMicros')::numeric)
  or (p_receipt->>'priceMicros')::numeric not between 0 and 9007199254740991
  or r.entry_policy is null or r.entry_policy not in ('spoken_v1','direct_recorded_v1')
  or p_receipt->'speechGatherUsed' is distinct from to_jsonb(r.entry_policy='spoken_v1' and (r.state='declined' or p_receipt->>'status'='completed'))
  or p_evidence is null or length(btrim(p_evidence)) not between 10 and 300 then raise exception 'Bound terminal carrier receipt required';end if;
 gather:=case when (p_receipt->>'speechGatherUsed')::boolean then 20000 else 0 end;
 if not icash_recording_private.keys(p_components,array['dealmachine','elevenlabs','twilio','messaging','email','llm','vercel','railway','supabase','github','payments','title_and_signing','support_and_overhead','acquisition','refund_and_dispute_reserve','other']) then raise exception 'Complete carrier-only costs required';end if;
 foreach cat in array array['dealmachine','elevenlabs','twilio','messaging','email','llm','vercel','railway','supabase','github','payments','title_and_signing','support_and_overhead','acquisition','refund_and_dispute_reserve','other'] loop
  part:=p_components->cat;
  if not icash_recording_private.keys(part,array['amountMicros','basis','evidenceRef'],case when cat='other' then array['subitems'] else '{}'::text[] end)
   or jsonb_typeof(part->'amountMicros') is distinct from 'number' or jsonb_typeof(part->'evidenceRef') is distinct from 'string'
   or length(btrim(part->>'evidenceRef')) not between 10 and 300 then raise exception 'Complete carrier-only component required';end if;
  n:=(part->>'amountMicros')::numeric;
  if n<0 or n<>trunc(n) or n>9007199254740991 then raise exception 'Invalid carrier-only amount';end if;
  if cat in ('elevenlabs','llm') then
   if n<>0 or part->>'basis' is distinct from 'not_applicable' then raise exception 'Unstarted AI is explicitly not applicable';end if;
  elsif coalesce(part->>'basis','') not in ('verified','estimated') then raise exception 'Explicit carrier-only cost basis required';end if;
  if part->>'basis'='estimated' then basis:='estimated';end if;
  total:=total+n;
 end loop;
 if total>9007199254740991 or p_components->'twilio'->>'basis' is distinct from 'verified'
  or (p_components->'twilio'->>'amountMicros')::numeric<>(p_receipt->>'priceMicros')::numeric
  or (p_components->'other'->>'amountMicros')::numeric<>gather
  or p_components->'other'->'subitems' is distinct from jsonb_build_object('speechGatherMicros',gather,'recordingMicros',0,'storageMicros',0)
  or (gather>0 and p_components->'other'->>'basis' is distinct from 'estimated') then raise exception 'Carrier or speech cost mismatch';end if;
 charge:=ceil(total*o.standard_cost_multiplier/10000);
 if charge>o.charge_cap_cents or o.rate_id<>r.rate_id or o.charge_cap_cents<>r.charge_cap_cents then return null;end if;
 insert into icash_recording_private.terminal_cost_receipts(recording_id,receipt,components,evidence_ref,charged_cents)
 values(r.id,p_receipt,p_components,p_evidence,charge) on conflict do nothing;
 select * into strict prior from icash_recording_private.terminal_cost_receipts where recording_id=r.id;
 if row(prior.receipt,prior.components,prior.evidence_ref,prior.charged_cents) is distinct from row(p_receipt,p_components,p_evidence,charge) then raise exception 'Terminal cost receipt conflict';end if;
 perform public.icash_settle_complete_costs(o.operation_key,charge,p_components,p_evidence);
 update public.icash_operation_spend set cost_basis=basis where operation_key=o.operation_key;
 update public.icash_voice_jobs set state='held',outcome='ended_before_recording',updated_at=icash_recording_private.clock_now() where id=r.voice_job_id and account_id=r.account_id and state in ('dispatching','dispatched');
 update public.icash_call_recordings set next_reconcile_at=null,reconcile_lease_token=null,reconcile_lease_expires_at=null,last_action='gate_settled',row_version=row_version+1,updated_at=icash_recording_private.clock_now() where id=r.id;
 return jsonb_build_object('settled',true,'operationKey',o.operation_key,'chargedCents',charge,'costBasis',basis);
end $function$

CREATE OR REPLACE FUNCTION icash_seller_recovery_private.settled_unanswered_call(p_account uuid, p_job uuid, p_contact uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j public.icash_voice_jobs;c public.icash_operational_contacts;r public.icash_call_recordings;
begin
 select * into j from public.icash_voice_jobs where id=p_job and account_id=p_account and operational_contact_id=p_contact;
 if not found or j.state is distinct from 'dispatched' or j.permission_id is not null or j.callback_id is not null
  or j.sms_source_message_id is not null or j.cancellation_notice_id is not null or j.meta_offer_lead_id is not null
  or j.meta_retry_of is not null or j.meta_followup_lead_id is not null then return false;end if;
 select * into c from public.icash_operational_contacts where id=p_contact and account_id=p_account and channel='voice';
 if not found then return false;end if;
 select * into r from public.icash_call_recordings where voice_job_id=j.id and account_id=p_account and party='seller'
  and operation_key='voice:'||j.id and screening_id=c.screening_id and to_phone=c.phone and contact_key=c.contact_key;
 if not found or r.call_sid is null or r.dial_claimed_at is null or r.dial_claimed_at>clock_timestamp()
  or public.icash_seller_recorded_call_finished(p_account,r.id) is not true
  or not exists(select 1 from public.icash_operation_spend where operation_key=r.operation_key and account_id=p_account and state='settled') then return false;end if;
 return exists(select 1 from public.icash_live_conversations conv where conv.account_id=p_account and conv.screening_id=c.screening_id
   and conv.operation_key=r.operation_key and conv.conversation_id=r.conversation_id and conv.contact_key=c.contact_key
   and conv.party='seller' and conv.state='complete' and conv.completed_at between r.dial_claimed_at and clock_timestamp()
   and conv.result->>'contactEvidence' in ('no_response','automated_answer')
   and public.icash_seller_call_disposition(conv.result) is null and not public.icash_call_has_seller_response(conv.result)
   and coalesce(conv.result->>'humanRequested','false')='false')
  or exists(select 1 from icash_recording_private.terminal_cost_receipts receipt where receipt.recording_id=r.id
   and receipt.receipt->>'status' in ('no-answer','busy')
   and row(receipt.receipt->>'providerAccountSid',receipt.receipt->>'callSid',receipt.receipt->>'fromPhone',receipt.receipt->>'toPhone')
    is not distinct from row(r.provider_account_sid,r.call_sid,r.from_phone,r.to_phone));
end $function$

CREATE OR REPLACE FUNCTION icash_seller_recovery_private.three_touch_call_current(p_account uuid, p_previous uuid, p_followup uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j public.icash_voice_jobs;root public.icash_voice_jobs;c public.icash_operational_contacts;
 previous_at timestamptz;first_at timestamptz;previous_sender text;root_sender text;allowed_jobs uuid[];
begin
 select * into j from public.icash_voice_jobs where id=p_previous and account_id=p_account;
 if not found or j.operational_contact_id is null then return false;end if;
 select * into c from public.icash_operational_contacts where id=j.operational_contact_id and account_id=p_account and channel='voice';
 if not found or c.revoked_at is not null or (c.eligibility_until>clock_timestamp()) is not true
  or public.icash_outreach_voice_current(p_account) is not true
  or public.icash_seller_response_operation_allowed(p_account,'voice:'||j.id) is not true
  or public.icash_operational_contact_current(p_account,c.id,'voice',false) is not true
  or not exists(select 1 from public.icash_accounts where id=p_account and not bot_paused)
  or not exists(select 1 from public.icash_wallets where account_id=p_account and balance_cents>reserved_cents)
  or exists(select 1 from public.icash_voice_jobs f where f.seller_followup_of=j.id and f.id is distinct from p_followup)
  or (p_followup is not null and not exists(select 1 from public.icash_voice_jobs f where f.id=p_followup and f.account_id=p_account and f.seller_followup_of=j.id and f.operational_contact_id=c.id))
  or icash_seller_recovery_private.settled_unanswered_call(p_account,j.id,c.id) is not true then return false;end if;
 select dial_claimed_at,from_phone into previous_at,previous_sender from public.icash_call_recordings where voice_job_id=j.id and account_id=p_account;
 if previous_at>clock_timestamp()-interval '2 hours' or previous_at<clock_timestamp()-interval '7 days' then return false;end if;
 first_at:=previous_at;allowed_jobs:=array[j.id];
 if j.seller_followup_of is not null then
  select * into root from public.icash_voice_jobs where id=j.seller_followup_of and account_id=p_account and operational_contact_id=c.id;
  if not found or root.seller_followup_of is not null
   or icash_seller_recovery_private.settled_unanswered_call(p_account,root.id,c.id) is not true then return false;end if;
  select dial_claimed_at,from_phone into first_at,root_sender from public.icash_call_recordings where voice_job_id=root.id and account_id=p_account;
  if first_at<clock_timestamp()-interval '7 days' or first_at>previous_at-interval '2 hours'
   or root_sender is distinct from previous_sender then return false;end if;
  allowed_jobs:=array[root.id,j.id];
 end if;
 -- Any real response exits the cold routine. The ordinary conversation/callback
 -- workflow owns the next action; absence of STOP alone never creates authority.
 if exists(select 1 from public.icash_text_threads t join public.icash_text_messages m on m.thread_id=t.id and m.account_id=t.account_id
   where t.recipient=c.phone and t.party='seller' and m.direction='incoming' and m.state='received' and (m.provider_id is not null or m.event_id is not null))
  or exists(select 1 from public.icash_live_conversations conv where conv.contact_key=c.contact_key and conv.party='seller' and conv.state='complete'
   and (public.icash_call_has_seller_response(conv.result) or public.icash_seller_call_disposition(conv.result) is not null))
  or exists(select 1 from icash_seller_agreement_private.call_history h where h.contact_key=c.contact_key
   and (public.icash_call_has_seller_response(jsonb_build_object('transcript',h.transcript)) or public.icash_seller_call_disposition(jsonb_build_object('transcript',h.transcript)) is not null))
  or exists(select 1 from public.icash_call_recordings other where other.to_phone=c.phone
   and (other.voice_job_id is null or other.voice_job_id<>all(allowed_jobs)) and other.voice_job_id is distinct from p_followup
   and other.dial_claimed_at is not null
   and (other.dial_claimed_at>=first_at or not public.icash_seller_recorded_call_finished(other.account_id,other.id)))
  or exists(select 1 from public.icash_customer_phone_calls human where human.recipient_phone=c.phone and human.child_sid is not null and human.created_at>=first_at)
 then return false;end if;
 return true;
end $function$

CREATE OR REPLACE FUNCTION icash_seller_recovery_private.meta_third_call_current(p_lead uuid, p_job uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m public.icash_meta_leads;l public.icash_seller_intakes;j public.icash_voice_jobs;r public.icash_call_recordings;
 first_at timestamptz;first_sender text;ids uuid[];previous_id uuid;
begin
 if not exists(select 1 from icash_seller_recovery_private.unanswered_policy where id=1 and enabled and three_touch_enabled) then return false;end if;
 select * into m from public.icash_meta_leads where lead_id=p_lead;
 if not found or m.first_outreach_at>now()-interval '24 hours' or m.first_outreach_at<now()-interval '72 hours' then return false;end if;
 select * into l from public.icash_seller_intakes where id=m.lead_id;
 if not found or l.contact_consent_scope='icash_x_demo' then return false;end if;
 select * into j from public.icash_voice_jobs where meta_followup_lead_id=m.lead_id and seller_followup_of is null and account_id=m.account_id;
 if not found or (p_job is null and exists(select 1 from public.icash_voice_jobs where meta_followup_lead_id=m.lead_id and seller_followup_of is not null)) then return false;end if;
 ids:=array[m.voice_job_id,j.id];
 if p_job is not null and not exists(select 1 from public.icash_voice_jobs f where f.id=p_job and f.account_id=m.account_id
  and f.meta_followup_lead_id=m.lead_id and f.seller_followup_of=j.id and f.permission_id=j.permission_id) then return false;end if;
 foreach previous_id in array ids loop
  select * into j from public.icash_voice_jobs where id=previous_id and account_id=m.account_id;
  if not found or j.state is distinct from 'dispatched' or not exists(select 1 from public.icash_contact_permissions p
   where p.id=j.permission_id and p.account_id=m.account_id and p.seller_intake_id=m.lead_id and p.screening_id=m.screening_id and p.phone=l.phone) then return false;end if;
  select * into r from public.icash_call_recordings where voice_job_id=j.id and account_id=m.account_id
   and operation_key='voice:'||j.id and screening_id=m.screening_id and party='seller' and to_phone=l.phone
   and contact_key=encode(sha256(convert_to(l.phone,'UTF8')),'hex');
  if not found or r.call_sid is null or r.dial_claimed_at is null or r.dial_claimed_at>now()-interval '2 hours'
   or public.icash_seller_recorded_call_finished(m.account_id,r.id) is not true
   or not exists(select 1 from public.icash_operation_spend where operation_key=r.operation_key and account_id=m.account_id and state='settled') then return false;end if;
  if first_at is null then first_at:=r.dial_claimed_at;first_sender:=r.from_phone;
  elsif r.dial_claimed_at<first_at+interval '2 hours' or r.from_phone is distinct from first_sender then return false;end if;
  if not exists(select 1 from public.icash_live_conversations c where c.account_id=m.account_id and c.screening_id=m.screening_id
   and c.contact_key=r.contact_key and c.operation_key=r.operation_key and c.conversation_id=r.conversation_id
   and c.party='seller' and c.state='complete' and c.completed_at between r.dial_claimed_at and now()
   and c.result->>'contactEvidence' in ('no_response','automated_answer') and not public.icash_call_has_seller_response(c.result)
   and public.icash_seller_call_disposition(c.result) is null and coalesce(c.result->>'humanRequested','false')='false')
   and not exists(select 1 from icash_recording_private.terminal_cost_receipts t where t.recording_id=r.id
    and t.receipt->>'status' in ('no-answer','busy') and row(t.receipt->>'providerAccountSid',t.receipt->>'callSid',t.receipt->>'fromPhone',t.receipt->>'toPhone')
     is not distinct from row(r.provider_account_sid,r.call_sid,r.from_phone,r.to_phone)) then return false;end if;
 end loop;
 if exists(select 1 from public.icash_call_recordings other where other.to_phone=l.phone and other.dial_claimed_at is not null
   and other.voice_job_id is distinct from p_job and (other.voice_job_id is null or other.voice_job_id<>all(ids))
   and (other.dial_claimed_at>=first_at or not public.icash_seller_recorded_call_finished(other.account_id,other.id)))
  or exists(select 1 from public.icash_customer_phone_calls human where human.recipient_phone=l.phone and human.child_sid is not null and human.created_at>=first_at)
  or exists(select 1 from public.icash_text_threads t join public.icash_text_messages msg on msg.thread_id=t.id and msg.account_id=t.account_id
   where t.recipient=l.phone and t.party='seller' and msg.direction='incoming' and msg.state='received' and (msg.provider_id is not null or msg.event_id is not null))
  or exists(select 1 from public.icash_live_conversations conv where conv.contact_key=encode(sha256(convert_to(l.phone,'UTF8')),'hex') and conv.party='seller' and conv.state='complete'
   and (public.icash_call_has_seller_response(conv.result) or public.icash_seller_call_disposition(conv.result) is not null))
  or exists(select 1 from icash_seller_agreement_private.call_history h where h.contact_key=encode(sha256(convert_to(l.phone,'UTF8')),'hex')
   and (public.icash_call_has_seller_response(jsonb_build_object('transcript',h.transcript)) or public.icash_seller_call_disposition(jsonb_build_object('transcript',h.transcript)) is not null))
 then return false;end if;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_queue_unanswered_seller_calls()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare candidate record;created integer:=0;added integer;visited boolean:=false;
begin
 perform pg_advisory_xact_lock(726341927);
 perform 1 from public.icash_operating_budget where id=1 and enabled for update;if not found then return 0;end if;
 perform public.icash_prepare_unanswered_seller_texts();
 for candidate in
  select j.id,j.account_id,j.operational_contact_id,r.id recording_id,r.dial_claimed_at from public.icash_call_recordings r
  join public.icash_voice_jobs j on j.id=r.voice_job_id and j.account_id=r.account_id
  join public.icash_operational_contacts c on c.id=j.operational_contact_id and c.account_id=j.account_id
  join public.icash_accounts a on a.id=j.account_id and not a.bot_paused
  join public.icash_wallets w on w.account_id=j.account_id and w.balance_cents>w.reserved_cents
  join icash_seller_recovery_private.unanswered_policy policy on policy.id=1 and policy.enabled
  where j.state='dispatched'
   and ((policy.three_touch_enabled and (j.seller_followup_of is null or exists(select 1 from public.icash_voice_jobs root
    where root.id=j.seller_followup_of and root.account_id=j.account_id and root.operational_contact_id=j.operational_contact_id and root.seller_followup_of is null))
    and r.dial_claimed_at between now()-interval '7 days' and now()-interval '2 hours')
    or (not policy.three_touch_enabled and j.seller_followup_of is null and j.created_at>=policy.activated_at
     and r.dial_claimed_at between greatest(policy.activated_at,now()-interval '24 hours') and now()-interval '2 hours'))
   and c.eligibility_until>now() and c.revoked_at is null
   and (policy.scan_at is null or (r.dial_claimed_at,r.id)>(policy.scan_at,policy.scan_id))
   and not exists(select 1 from public.icash_voice_jobs f where f.seller_followup_of=j.id)
  order by r.dial_claimed_at,r.id limit 20
 loop
  visited:=true;
  update icash_seller_recovery_private.unanswered_policy set scan_at=candidate.dial_claimed_at,scan_id=candidate.recording_id where id=1;
  if public.icash_unanswered_seller_call_current(candidate.account_id,candidate.id) then
   insert into public.icash_voice_jobs(account_id,operational_contact_id,seller_followup_of,due_at)
    values(candidate.account_id,candidate.operational_contact_id,candidate.id,clock_timestamp()) on conflict do nothing;
   get diagnostics added=row_count;created:=created+added;
  end if;
 end loop;
 if not visited then update icash_seller_recovery_private.unanswered_policy set scan_at=null,scan_id=null where id=1;end if;
 return created;
end $function$
